/// <summary>
/// CB790_DiscountClaim
/// </summary>
internal final class METGUPDiscountClaimProcess extends GUPDiscountClaimProcess
{
    private LedgerJournalTable METLedgerJournalTable;
    private VendAccount METCurVendAccount;
    private CurrencyCode METCurCurrencyCode;
    private InvoiceId METCurInvoiceId;
    private Voucher METCurVoucher;
    private date METCurProcessDate;
    private GUPDiscountVendorClaimGroupName METCurDiscountClaimGroup;
    private DimensionDefault METCurVendDefaultDimension;
    private Set METInvoiceIdWithAmountFee = new Set(Types::String);
    private TaxGroup METCurVendTaxGroup;
}

Method.Source:
    //private GUPInstrumentationLogger METLogger; // Declare as a global variable
    
    /// <summary>
    /// Copied from GUPDiscountClaimProcess so we can call custom version of METProcess
    /// </summary>
    /// <param name = "_queryRun">Query of discount claims to process</param>
    public static void processClaims(QueryRun _queryRun)
    {
        METGUPDiscountClaimProcess discountClaimProcess = new METGUPDiscountClaimProcess();
        //GUPInstrumentationLogger instrumentionalogger = GUPInstrumentationLogger::createLogger(classStr(GUPDiscountClaimProcess));

        /*using (SysInstrumentationActivityContext activityContext = instrumentionalogger.discountClaimProcess().processClaims())
        {*/
        try
        {
            ttsbegin;
            
            while (_queryRun.next())
            {
                GUPDiscountClaim discountClaim = _queryRun.get(tableNum(GUPDiscountClaim));
                setPrefix(strFmt("@GlobalUnifiedPricing:DiscountClaimPrefix", discountClaim.DiscountClaimId));

                discountClaimProcess.METProcess(discountClaim);
            }

            if (discountClaimProcess.METCurInvoiceId)
            {
                Amount claimFeeAmount = discountClaimProcess.METCreateClaimFeeLedgerJournalTransOffset(discountClaimProcess.METCurInvoiceId);
                discountClaimProcess.METCreateOrUpdateClaimLedgerJournalTransVend(claimFeeAmount);
            }

            discountClaimProcess.METPostClaimJournal();

            ttscommit;
        }
        catch (Exception::Error)
        {
            exceptionTextFallThrough();
        }
        //}
    }

    private void METProcess(GUPDiscountClaim _discountClaim)
    {
        /*using (var activityContext = this.instrumentationLogger().discountClaimProcess().process())
        {*/
        if (_discountClaim.Status == GUPDiscountClaimStatus::Calculated)
        {
            if (METCurVendAccount  != _discountClaim.VendorAccount
                || METCurCurrencyCode != _discountClaim.CurrencyCode)
            {
                if (METCurInvoiceId)
                {
                    Amount claimFeeAmount = this.METCreateClaimFeeLedgerJournalTransOffset(METCurInvoiceId);
                    this.METCreateOrUpdateClaimLedgerJournalTransVend(claimFeeAmount);
                }

                this.METPostClaimJournal();

                // Create new journal table for different vendor.
                METCurVendAccount = _discountClaim.VendorAccount;
                METCurCurrencyCode = _discountClaim.CurrencyCode;
                METCurInvoiceId = this.METGetVendorInvoiceClaimJournalNumberSeq().num();
                METCurVoucher = this.METGetClaimJournalVoucherNumberSeq().voucher();
                METCurProcessDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

                VendTable vendTable;
                select firstonly GUPDiscountVendorClaimGroupName, DefaultDimension, TaxGroup from vendTable where vendTable.AccountNum == METCurVendAccount;
                METCurDiscountClaimGroup = vendTable.GUPDiscountVendorClaimGroupName;
                METCurVendDefaultDimension = vendTable.DefaultDimension;
                METCurVendTaxGroup = vendTable.TaxGroup;
                if (!METCurDiscountClaimGroup)
                {
                    info(strFmt("@GlobalUnifiedPricing:GUPVendoDiscountClaimGroupNotSet", METCurVendAccount));
                }
                this.METCreateClaimLedgerJournalTable(this.METLedgerJournalNameProcess());
            }

            this.METCalculateClaimPercentFee(_discountClaim.DiscountClaimId);

            if (!METInvoiceIdWithAmountFee.in(METCurInvoiceId))
            {
                //this.METCalculateClaimAmountFee(); // claim % only
                METInvoiceIdWithAmountFee.add(METCurInvoiceId);
            }

            // Create journal trans.
            Amount claimAmount = this.METCreateClaimLedgerJournalTransOffset(_discountClaim);
            this.METCreateOrUpdateClaimLedgerJournalTransVend(claimAmount);

            _discountClaim.selectForUpdate(true);
            _discountClaim.VendorClaimInvoice = METCurInvoiceId;
            _discountClaim.Status = GUPDiscountClaimStatus::Claimed;
            _discountClaim.update();
        }
        //}
    }

    private void METCreateOrUpdateClaimLedgerJournalTransVend(Amount _claimAmount)
    {
        LedgerJournalTrans ledgerJournalTrans;

        if (_claimAmount == 0)
        {
            return;
        }

        select forupdate RecId, AmountCurCredit, AmountCurDebit, CurrencyCode from ledgerJournalTrans
            where ledgerJournalTrans.JournalNum  == METLedgerJournalTable.JournalNum
                && ledgerJournalTrans.AccountType == LedgerJournalACType::Vend;

        if (!ledgerJournalTrans)
        {
            ledgerJournalTrans.clear();
            ledgerJournalTrans.initValue();
            ledgerJournalTrans.Txt                   = "@GlobalUnifiedPricing:DiscountClaim";
            ledgerJournalTrans.JournalNum            = METLedgerJournalTable.JournalNum;
            ledgerJournalTrans.Voucher               = METCurVoucher;
            ledgerJournalTrans.Invoice               = METCurInvoiceId;
            ledgerJournalTrans.DocumentDate          = METCurProcessDate;
            ledgerJournalTrans.TransDate             = METCurProcessDate;
            ledgerJournalTrans.CurrencyCode          = METCurCurrencyCode;
            ledgerJournalTrans.AmountCurDebit        = _claimAmount >= 0 ? _claimAmount : 0;
            ledgerJournalTrans.AmountCurCredit       = _claimAmount >= 0 ? 0 : -_claimAmount;
            ledgerJournalTrans.TaxGroup              = METCurVendTaxGroup;
            ledgerJournalTrans.Approved              = NoYes::Yes;
            ledgerJournalTrans.Approver              = HcmWorker::userId2Worker(curUserId());
            ledgerJournalTrans.ExchRate              = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.ExchRateSecond        = ExchangeRateHelper::exchRateSecond(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.AccountType           = LedgerJournalACType::Vend;
            ledgerJournalTrans.parmAccount(METCurVendAccount);
        }
        else
        {
            ledgerJournalTrans.AmountCurDebit  += _claimAmount >= 0 ? _claimAmount : 0;
            ledgerJournalTrans.AmountCurCredit += _claimAmount >= 0 ? 0 : -_claimAmount;

            if (ledgerJournalTrans.AmountCurDebit != 0 && ledgerJournalTrans.AmountCurCredit != 0)
            {
                ledgerJournalTrans.AmountCurDebit  = ledgerJournalTrans.AmountCurDebit > ledgerJournalTrans.AmountCurCredit ? ledgerJournalTrans.AmountCurDebit - ledgerJournalTrans.AmountCurCredit : 0;
                ledgerJournalTrans.AmountCurCredit = ledgerJournalTrans.AmountCurDebit > ledgerJournalTrans.AmountCurCredit ? 0 : ledgerJournalTrans.AmountCurCredit - ledgerJournalTrans.AmountCurDebit;
            }
        }

        ledgerJournalTrans.write();
    }

    private Amount METCreateClaimLedgerJournalTransOffset(GUPDiscountClaim _gupDiscountClaim)
    {
        LedgerJournalTrans ledgerJournalTrans;
        GUPDiscountClaimTransaction claimTrans;
        Amount totalAmount;

        while select ItemNumber, LedgerAccount, Amount from claimTrans
            where claimTrans.DiscountClaimId == _gupDiscountClaim.DiscountClaimId
        {
            totalAmount += claimTrans.Amount;

            ledgerJournalTrans.clear();
            ledgerJournalTrans.initValue();
            ledgerJournalTrans.Txt             = strFmt("%1 %2 %3", "@GlobalUnifiedPricing:DiscountClaimAccrual", "@SYS77038", "@SYS8776");
            ledgerJournalTrans.JournalNum      = METLedgerJournalTable.JournalNum;
            ledgerJournalTrans.Voucher         = METCurVoucher;
            ledgerJournalTrans.Invoice         = METCurInvoiceId;
            ledgerJournalTrans.DocumentDate    = METCurProcessDate;
            ledgerJournalTrans.TransDate       = METCurProcessDate;
            ledgerJournalTrans.CurrencyCode    = METCurCurrencyCode;
            ledgerJournalTrans.AmountCurDebit  = claimTrans.Amount >= 0 ? 0 : -claimTrans.Amount;
            ledgerJournalTrans.AmountCurCredit = claimTrans.Amount >= 0 ? claimTrans.Amount : 0;
            ledgerJournalTrans.TaxGroup        = METCurVendTaxGroup;
            ledgerJournalTrans.TaxItemGroup    = InventTable::find(claimTrans.ItemNumber).purchTaxItemGroupId();
            ledgerJournalTrans.Approved        = NoYes::Yes;
            ledgerJournalTrans.Approver        = HcmWorker::userId2Worker(curUserId());
            ledgerJournalTrans.ExchRate        = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.ExchRateSecond  = ExchangeRateHelper::exchRateSecond(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.AccountType     = LedgerJournalACType::Ledger;
            ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(claimTrans.LedgerAccount);
            ledgerJournalTrans.insert();
        }

        return totalAmount;
    }

    private NumberSequenceCode METLedgerJournalNameVoucher(LedgerJournalName _ledgerJournalName)
    {
        NumberSequenceTable numberSequenceTable = NumberSequenceTable::find(_ledgerJournalName.NumberSequenceTable);

        return numberSequenceTable.NumberSequence;
    }

    private NumberSeq METGetVendorInvoiceClaimJournalNumberSeq()
    {
        NumberSeq               numberSeq;
        NumberSequenceReference numberSequenceReference;
        NumberSequenceTable     numberSequenceTable;

        numberSequenceReference = GUPParameters::numRefDiscountVendorClaimJournalInvoice();

        numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

        if (numberSequenceTable)
        {
            if (numberSequenceTable.Manual == NoYes::Yes)
            {
                throw error(strFmt("@SYS131762", "@GlobalUnifiedPricing:GUPDiscountVendorClaimJournalInvoice"));
            }
            else
            {
                numberSeq = NumberSeq::newGetNum(numberSequenceReference);
            }
        }

        if (numberSeq == null)
        {
            throw error(strfmt("@GLS111556", new DictType(extendedtypenum(GUPDiscountVendorClaimJournalInvoice)).label(), "@GlobalUnifiedPricing:GUPParameters"));
        }
      
        return numberSeq;
    }

    private void METCalculateClaimPercentFee(GUPDiscountClaimId _discountClaimId)
    {
        GUPDiscountClaimTransaction claimTrans;
        GUPDiscountClaim    discountClaim;
        METClaimSetup       claimSetup;

        /*GUPDiscountVendorClaimFee claimFee;
        GUPDiscountVendorClaimFeeSetup claimFeeSetup;*/
        GUPDiscountVendorClaimFeeCalculation claimFeeCalculation;

        select sum(Amount) from claimTrans
            where claimTrans.DiscountClaimId == _discountClaimId;

        /* Do not check standard table for claim fee setup as this will be empty, use METClaimSetup instead
        while select ClaimFeeId, CalcType, Value, RecId, TaxItemGroup from claimFeeSetup
            where claimFeeSetup.CalcType == GUPDiscountClaimCalcType::Percent &&
                (claimFeeSetup.VendorCode == TableGroupAll::All ||
                (claimFeeSetup.VendorCode == TableGroupAll::Table && claimFeeSetup.AccountSelection == METCurVendAccount) ||
                (claimFeeSetup.VendorCode == TableGroupAll::GroupId && claimFeeSetup.AccountSelection == METCurDiscountClaimGroup))
            join FeeAccount from claimFee
            where claimFee.FeeId == claimFeeSetup.ClaimFeeId*/
        
        // The % fee is applied to discount claims raised if the combination of site/supplier/component has a % fee attached in METClaimSetup
        while select AdminFee, FeeAccount, RecId from claimSetup
                join discountClaim
               where discountClaim.METInventSiteId  == claimSetup.SiteId
                  && discountClaim.VendorAccount    == claimSetup.Supplier
                  && discountClaim.METComponent     == claimSetup.Component
                  && discountClaim.DiscountClaimId  == _discountClaimId
        {
            claimFeeCalculation.clear();
            claimFeeCalculation.DiscountClaimId = _discountClaimId;
            //claimFeeCalculation.FeeId = claimFeeSetup.ClaimFeeId; // Used in ledgerJournalTrans.Txt for createClaimFeeLedgerJournalTransOffset
            //claimFeeCalculation.FeeSetupRecId = claimFeeSetup.RecId;
            claimFeeCalculation.FeeSetupRecId = claimSetup.RecId;
            
            // admin fee amount is excluding GST and TaxItemGroup set to GST
            claimFeeCalculation.Amount = claimTrans.Amount * (claimSetup.AdminFee * 0.01);
            claimFeeCalculation.VendorClaimInvoice = METCurInvoiceId;
            // force to percentage
            //claimFeeCalculation.CalcType = claimFeeSetup.CalcType; 
            claimFeeCalculation.CalcType = GUPDiscountClaimCalcType::Percent;
            // GST for journal as per standard
            claimFeeCalculation.TaxItemGroup = METConstants::taxGroupGST;
            claimFeeCalculation.FeeAccount = claimSetup.FeeAccount;
            claimFeeCalculation.insert();
        }
    }

