    private Amount METCreateClaimFeeLedgerJournalTransOffset(InvoiceId _invoiceId)
    {
        LedgerJournalTrans ledgerJournalTrans;
        GUPDiscountVendorClaimFeeCalculation feeCalc;
        Amount totalAmount;

        while select FeeId, TaxItemGroup, FeeAccount, sum(Amount) from feeCalc
            group by FeeId, TaxItemGroup, FeeAccount
            where feeCalc.VendorClaimInvoice == _invoiceId
        {
            totalAmount += feeCalc.Amount;

            ledgerJournalTrans.clear();
            ledgerJournalTrans.initValue();
            ledgerJournalTrans.Txt                   = strFmt("%1 %2 %3", "@GlobalUnifiedPricing:GUPDiscountVendorClaimFee", "@SYS77038", feeCalc.FeeId);
            ledgerJournalTrans.JournalNum            = METLedgerJournalTable.JournalNum;
            ledgerJournalTrans.Voucher               = METCurVoucher;
            ledgerJournalTrans.Invoice               = METCurInvoiceId;
            ledgerJournalTrans.DocumentDate          = METCurProcessDate;
            ledgerJournalTrans.TransDate             = METCurProcessDate;
            ledgerJournalTrans.CurrencyCode          = METCurCurrencyCode;
            ledgerJournalTrans.AmountCurDebit        = feeCalc.Amount >= 0 ? 0 : -feeCalc.Amount;
            ledgerJournalTrans.AmountCurCredit       = feeCalc.Amount >= 0 ? feeCalc.Amount : 0;
            ledgerJournalTrans.TaxGroup              = METCurVendTaxGroup;
            ledgerJournalTrans.TaxItemGroup          = feeCalc.TaxItemGroup;
            ledgerJournalTrans.Approved              = NoYes::Yes;
            ledgerJournalTrans.Approver              = HcmWorker::userId2Worker(curUserId());
            ledgerJournalTrans.ExchRate              = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.ExchRateSecond        = ExchangeRateHelper::exchRateSecond(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.AccountType           = LedgerJournalACType::Ledger;
            ledgerJournalTrans.LedgerDimension       = LedgerDimensionFacade::serviceCreateLedgerDimension(feeCalc.FeeAccount, METCurVendDefaultDimension);
            ledgerJournalTrans.insert();
        }

        return totalAmount;
    }
